-- lovable-cron-fallback-reviewed: one-off bounded backfill of thousands of CJ products, 100 per minute, automatically unscheduled when drained; synchronous bulk updates time out under product triggers.
CREATE OR REPLACE FUNCTION public.backfill_cj_origin_batch() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.products SET origin_country_id = (SELECT id FROM public.countries WHERE code = 'CN' LIMIT 1) WHERE id IN (SELECT id FROM public.products WHERE source = 'cj_import' AND origin_country_id IS NULL ORDER BY id LIMIT 100); IF NOT EXISTS (SELECT 1 FROM public.products WHERE source = 'cj_import' AND origin_country_id IS NULL LIMIT 1) THEN PERFORM cron.unschedule('backfill-cj-origin'); END IF; END $$; REVOKE ALL ON FUNCTION public.backfill_cj_origin_batch() FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.backfill_cj_origin_batch() TO service_role; SELECT cron.schedule('backfill-cj-origin', '* * * * *', 'SELECT public.backfill_cj_origin_batch()');